var queryLimitRe = regexp.MustCompile(`(?is)\bLIMIT\s+(\d+)\s*;?\s*$`)

func queryRowCap(query string) (int, bool) {
	m := queryLimitRe.FindStringSubmatch(query)
	if m == nil { return 0, false }
	n, err := strconv.Atoi(m[1])
	if err != nil || n < 2 { return 0, false }   // LIMIT 1 == fetch-one idiom, not a cap
	return n, true
}

func resultHitItsRowCap(query string, rowCount int) (limit int, hit bool) {
	n, ok := queryRowCap(query)
	if !ok { return 0, false }
	return n, rowCount >= n
}

